import pytest

from bedrock_protocol import v1001, v2168, v2225

VERSIONS = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735:
# packet.ServerToClientHandshake{JWT: []byte("eyJhbGciOiJFUzM4NCJ9.e30.c2ln")}
TOKEN = bytes.fromhex("1d65794a68624763694f694a46557a4d344e434a392e6533302e63326c6e")

# generated by gophertunnel b8bd735:
# packet.ServerToClientHandshake{JWT: []byte{}}
EMPTY = bytes.fromhex("00")

# generated by gophertunnel b8bd735:
# packet.ServerToClientHandshake{JWT: []byte(strings.Repeat("x", 130))}
LONG = bytes.fromhex(
    "8201787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878"
    "7878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878787878"
    "7878787878787878787878787878787878787878787878787878787878787878"
)

GOLDENS = [
    *[
        pytest.param(
            version.ServerToClientHandshakePacket(token="eyJhbGciOiJFUzM4NCJ9.e30.c2ln"),
            TOKEN,
            id=f"{version.__name__.rpartition('.')[2]}-token",
        )
        for version in VERSIONS
    ],
    *[
        pytest.param(
            version.ServerToClientHandshakePacket(token=""),
            EMPTY,
            id=f"{version.__name__.rpartition('.')[2]}-empty-token",
        )
        for version in VERSIONS
    ],
    *[
        pytest.param(
            version.ServerToClientHandshakePacket(token="x" * 130),
            LONG,
            id=f"{version.__name__.rpartition('.')[2]}-token-past-127-bytes",
        )
        for version in VERSIONS
    ],
]


@pytest.mark.parametrize("version", VERSIONS, ids=lambda version: version.__name__.rpartition(".")[2])
def test_server_to_client_handshake_is_packet_3(version):
    assert version.PACKETS[3] is version.ServerToClientHandshakePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_server_to_client_handshake_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_server_to_client_handshake_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
